def auto_clean_for_kaggle(train_df, test_df):
    print('--- とりあえず全部のデータを自動で修正処理を行う ---')
    df_list = [pandas.core.frame.DataFrame, pandas.core.frame.DataFrame]
    print('\n[ステップ1] 欠損値の処理を開始...')
    missing_in_train = [col for col in pandas.core.frame.DataFrame.columns.drop('SalePrice', errors='ignore') if pandas.core.frame.DataFrame[col].isnull().sum() > 0]
    missing_in_test = [col for col in pandas.core.frame.DataFrame.columns if pandas.core.frame.DataFrame[col].isnull().sum() > 0]
    all_missing_cols = list(set(missing_in_train + missing_in_test))
    if not all_missing_cols:
        print('-> 欠損値のある列は見つかりませんでした。')
    else:
        print(f'-> 対象列 (計{len(all_missing_cols)}列) の処理を開始...')
        for col in all_missing_cols:
            for df in df_list:
                if col in df.columns:
                    flag_col_name = f'{col}_is_missing'
                    df[flag_col_name] = df[col].isnull()
                    df[col].fillna(0, inplace=True)
    print('-> 欠損フラグの追加と0での補完が完了しました。')
    print('\n[ステップ2] 外れ値の処理を開始...')
    numerical_cols = pandas.core.frame.DataFrame.select_dtypes(include=numpy.number).columns.tolist()
    cols_to_exclude = ['Id', 'MSSubClass', 'SalePrice'] + [col for col in pandas.core.frame.DataFrame.columns if '_is_missing' in col]
    target_numerical_cols = [col for col in numerical_cols if col not in cols_to_exclude]
    print(f'-> {len(target_numerical_cols)}個の数値列を対象に処理します。')
    for col in target_numerical_cols:
        q01 = pandas.core.frame.DataFrame[col].quantile(0.01)
        q99 = pandas.core.frame.DataFrame[col].quantile(0.99)
        for df in df_list:
            if col in df.columns:
                df[col] = df[col].clip(lower=q01, upper=q99)
    print('-> 外れ値の丸め処理 (Clipping) が完了しました。')
    print('\n--- 全ての自動修正処理が完了しました ---')
    return (pandas.core.frame.DataFrame, pandas.core.frame.DataFrame)

