        if all((str in pandas.core.frame.DataFrame.columns for str in ['TotalBsmtSF', '1stFlrSF', '2ndFlrSF'])):
            pandas.core.frame.DataFrame['TotalSF'] = pandas.core.frame.DataFrame['TotalBsmtSF'] + pandas.core.frame.DataFrame['1stFlrSF'] + pandas.core.frame.DataFrame['2ndFlrSF']
        if all((str in pandas.core.frame.DataFrame.columns for str in ['FullBath', 'HalfBath', 'BsmtFullBath', 'BsmtHalfBath'])):
            pandas.core.frame.DataFrame['TotalBath'] = pandas.core.frame.DataFrame['FullBath'] + 0.5 * pandas.core.frame.DataFrame['HalfBath'] + pandas.core.frame.DataFrame['BsmtFullBath'] + 0.5 * pandas.core.frame.DataFrame['BsmtHalfBath']
        outdoor_cols = ['WoodDeckSF', 'OpenPorchSF', 'ScreenPorch']
        available_outdoor = [str for str in outdoor_cols if str in pandas.core.frame.DataFrame.columns]
        if available_outdoor:
            pandas.core.frame.DataFrame['TotalOutdoorSF'] = pandas.core.frame.DataFrame[available_outdoor].sum(axis=1)
        if all((str in pandas.core.frame.DataFrame.columns for str in ['YrSold', 'YearBuilt'])):
            pandas.core.frame.DataFrame['HouseAge'] = pandas.core.frame.DataFrame['YrSold'] - pandas.core.frame.DataFrame['YearBuilt']
        if all((str in pandas.core.frame.DataFrame.columns for str in ['YrSold', 'YearRemodAdd', 'YearBuilt'])):
            pandas.core.frame.DataFrame['RemodAge'] = pandas.core.frame.DataFrame['YrSold'] - pandas.core.frame.DataFrame['YearRemodAdd']
            pandas.core.frame.DataFrame['IsRemodeled'] = (pandas.core.frame.DataFrame['YearRemodAdd'] != pandas.core.frame.DataFrame['YearBuilt']).astype(int)
        if 'HouseAge' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['IsNew'] = (pandas.core.frame.DataFrame['HouseAge'] <= 5).astype(int)
        if 'TotalSF' in pandas.core.frame.DataFrame.columns and 'GrLivArea' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['LivingAreaRatio'] = pandas.core.frame.DataFrame['GrLivArea'] / (pandas.core.frame.DataFrame['TotalSF'] + 1)
        if all((str in pandas.core.frame.DataFrame.columns for str in ['BsmtFinSF1', 'TotalBsmtSF'])):
            pandas.core.frame.DataFrame['BsmtFinishedRatio'] = pandas.core.frame.DataFrame['BsmtFinSF1'] / (pandas.core.frame.DataFrame['TotalBsmtSF'] + 1)
        if all((str in pandas.core.frame.DataFrame.columns for str in ['LotArea', 'TotRmsAbvGrd'])):
            pandas.core.frame.DataFrame['LotAreaPerRoom'] = pandas.core.frame.DataFrame['LotArea'] / (pandas.core.frame.DataFrame['TotRmsAbvGrd'] + 1)
        if all((str in pandas.core.frame.DataFrame.columns for str in ['OverallQual', 'GrLivArea'])):
            pandas.core.frame.DataFrame['QualityArea'] = pandas.core.frame.DataFrame['OverallQual'] * pandas.core.frame.DataFrame['GrLivArea']
        if all((str in pandas.core.frame.DataFrame.columns for str in ['OverallQual', 'OverallCond'])):
            pandas.core.frame.DataFrame['OverallScore'] = pandas.core.frame.DataFrame['OverallQual'] * pandas.core.frame.DataFrame['OverallCond']
        quality_cols = ['ExterQual', 'KitchenQual', 'BsmtQual', 'GarageQual']
        available_qual = [str for str in quality_cols if str in pandas.core.frame.DataFrame.columns]
        if available_qual:
            pandas.core.frame.DataFrame['AvgQuality'] = pandas.core.frame.DataFrame[available_qual].mean(axis=1)
        if 'OverallQual' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['QualitySquared'] = pandas.core.frame.DataFrame['OverallQual'] ** 2
        if '2ndFlrSF' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['Has2ndFloor'] = (pandas.core.frame.DataFrame['2ndFlrSF'] > 0).astype(int)
        if 'TotalBsmtSF' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['HasBasement'] = (pandas.core.frame.DataFrame['TotalBsmtSF'] > 0).astype(int)
        if 'GarageArea' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['HasGarage'] = (pandas.core.frame.DataFrame['GarageArea'] > 0).astype(int)
        if 'Fireplaces' in pandas.core.frame.DataFrame.columns:
            pandas.core.frame.DataFrame['HasFireplace'] = (pandas.core.frame.DataFrame['Fireplaces'] > 0).astype(int)
        if all((str in pandas.core.frame.DataFrame.columns for str in ['GarageCars', 'GarageQual'])):
            pandas.core.frame.DataFrame['GarageScore'] = pandas.core.frame.DataFrame['GarageCars'] * (pandas.core.frame.DataFrame['GarageQual'] + 1)
        return pandas.core.frame.DataFrame
